INSERT INTO coop_info (item_number, curriculum, category, title, description, gpa_requirement, academic_year) VALUES
  (1, 'all', 'qualification','คุณสมบัติทั่วไป','เป็นนักศึกษาสาขาวิชาวิทยาการคอมพิวเตอร์ คณะวิทยาศาสตร์ฯ ม.ธรรมศาสตร์',NULL, 2568),
  (2, '61', 'required_course','รายวิชาที่ต้องเคยศึกษา','เคยศึกษา วิชา คพ.101, คพ.102, คพ.111, (คพ.213 หรือ 216), คพ.251 และ คพ.264 โดยที่เกรดเฉลี่ยของรายวิชากลุ่มนี้ไม่ต่ำกว่า 2.5',2.50, 2568),
  (2, '66', 'required_course','รายวิชาที่ต้องเคยศึกษา','เคยศึกษา วิชา คพ.100, คพ.101, คพ.102, คพ.111, (คพ.213 หรือ 216), คพ.251 และ คพ.261 โดยที่เกรดเฉลี่ยของรายวิชากลุ่มนี้ไม่ต่ำกว่า 2.5',2.50, 2568),
  (3, '61', 'required_course','รายวิชาที่กำลังศึกษา หรือเคยศึกษา','กำลังศึกษา หรือเคยศึกษาวิชา คพ.384 และ วิชา (คพ.266 หรือ 322 หรือ 348)',NULL, 2568),
  (3, '66', 'required_course','รายวิชาที่กำลังศึกษา หรือเคยศึกษา','กำลังศึกษา หรือเคยศึกษาวิชา คพ.180 และ วิชา (คพ.262 หรือ 331 หรือ 240)',NULL, 2568),
  (4, '61', 'required_course','รายวิชาที่ต้องสอบผ่านก่อนออกปฏิบัติงาน','จะต้องสอบได้วิชา คพ.302 ก่อนออกไปปฏิบัติงานจริง ณ สถานประกอบการ',NULL, 2568),
  (4, '66', 'required_course','รายวิชาที่ต้องสอบผ่านก่อนออกปฏิบัติงาน','จะต้องสอบได้วิชา คพ.301 ก่อนออกไปปฏิบัติงานจริง ณ สถานประกอบการ',NULL, 2568),
  (5, 'all', 'gpa','ผลการเรียนเฉลี่ยสะสม','มีผลการเรียนเฉลี่ยสะสม (GPA) เมื่อสิ้นภาคการศึกษาสุดท้ายก่อนสมัครเข้าเป็นนักศึกษาสหกิจศึกษาไม่ต่ำกว่า 2.75',2.75, 2568),
  (6, 'all', 'behavior','ความประพฤติ','มีความประพฤติเรียบร้อย ไม่เคยถูกลงโทษทางวินัยนักศึกษา',NULL, 2568),
  (7, 'all', 'qualification','การยอมรับเงื่อนไข','รับทราบเกณฑ์และลงนามยอมรับว่าจะปฏิบัติตามเงื่อนไขและกระบวนการสหกิจศึกษาอย่างครบถ้วน',NULL, 2568);
